head.script:
scwin.screenId = "jldinf92200_reportresult";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_5", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.method" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("method"))==='srchReport13'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "<![CDATA[" + String(dma_map.get("isurCd")) + "]]\u003e"; } },
        { childId: "__rb1", fn: function () { return "<![CDATA[" + String(dma_map.get("isurNm")) + "]]\u003e"; } },
        { childId: "__rb2", fn: function () { return "<![CDATA[" + String(dma_map.get("stdCd")) + "]]\u003e"; } },
        { childId: "__rb3", fn: function () { return "<![CDATA[" + String(dma_map.get("activTpNm")) + "]]\u003e"; } },
        { childId: "__rb4", fn: function () { return "<![CDATA[" + String(dma_map.get("stdIndicTpNm")) + "]]\u003e"; } },
        { childId: "__rb5", fn: function () { return "<![CDATA[" + String(dma_map.get("isuNm")) + "]]\u003e"; } },
        { childId: "__rb6", fn: function () { return "<![CDATA[" + String(dma_map.get("isuAbbrv")) + "]]\u003e"; } },
        { childId: "__rb7", fn: function () { return "<![CDATA[" + String(dma_map.get("isuEngNm")) + "]]\u003e"; } },
        { childId: "__rb8", fn: function () { return "<![CDATA[" + String(dma_map.get("isuEngAbbrv")) + "]]\u003e"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf92200_reportresult.onpageload' });
    }
};


